import{at as e,it as t,n,vt as r}from"./chunks/framework.pB6ycoEm.js";var i=JSON.parse(`{"title":"How to set a version part to a specific value","description":"","frontmatter":{},"headers":[],"relativePath":"howtos/set-a-part-to-a-value/index.md","filePath":"howtos/set-a-part-to-a-value.md","lastUpdated":1793537972000}`),a={name:`howtos/set-a-part-to-a-value/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="how-to-set-a-version-part-to-a-specific-value" tabindex="-1">How to set a version part to a specific value <a class="header-anchor" href="#how-to-set-a-version-part-to-a-specific-value" aria-label="Permalink to “How to set a version part to a specific value”">​</a></h1><p>Normally <code>bump</code> increments a part by one step. Sometimes you want to jump a part straight to a value instead, such as moving from a pre-release to the final release, or forcing a <code>1.0.0</code> release. Use <code>--to</code> with the part you want to change:</p><div class="language-console" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bump-my-version bump major --to 1</span></span></code></pre></div><p>With a current version of <code>0.9.3</code>, the new version is <code>1.0.0</code>. Like a normal bump, the parts that depend on the changed part (<code>minor</code> and <code>patch</code> here) are reset to their first value.</p><h2 id="jumping-to-the-last-value-in-a-list" tabindex="-1">Jumping to the last value in a list <a class="header-anchor" href="#jumping-to-the-last-value-in-a-list" aria-label="Permalink to “Jumping to the last value in a list”">​</a></h2><p>Given this configuration:</p><div class="language-toml" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bumpversion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">parts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">release</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">optional_value = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;final&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">values = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;beta&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;final&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>You can skip straight to the final release from any pre-release:</p><div class="language-console" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bump-my-version bump release --to final</span></span></code></pre></div><h2 id="things-to-know" tabindex="-1">Things to know <a class="header-anchor" href="#things-to-know" aria-label="Permalink to “Things to know”">​</a></h2><ul><li><code>--to</code> takes one part per run. To set several parts at once, use <code>--new-version</code> with the whole version.</li><li><code>--to</code> and <code>--new-version</code> cannot be used together, and <code>--to</code> requires a version part.</li><li>The value must be valid for the part. For a part with <code>values</code>, it must be one of them. For a numeric part, it must contain a number that is not lower than the <code>first_value</code>. It <em>can</em> be lower than the current value.</li><li>CalVer parts are based on the date and cannot be set with <code>--to</code>.</li><li>Parts that always increment (<code>always_increment</code>) still increment, as they do in a normal bump.</li><li><code>include_bumps</code> and <code>exclude_bumps</code> file filters apply to the part named on the command line.</li></ul>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};